Here's your expense tracker. Add an item with its amount and category, and the total and category split update as you go. Entries stay on this page only until you close it.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body{font-family:Segoe UI,Arial,sans-serif;margin:0;padding:16px;background:#f7f7f9;color:#222}
  h2{margin:0 0 12px}
  .row{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px}
  input,select,button{padding:8px;border:1px solid #ccc;border-radius:6px;font-size:14px}
  input[type=text]{flex:2;min-width:120px}
  input[type=number]{flex:1;min-width:90px}
  button{background:#2563eb;color:#fff;border:none;cursor:pointer}
  .card{background:#fff;border-radius:10px;padding:12px;margin-bottom:12px;box-shadow:0 1px 3px #0002}
  .total{font-size:26px;font-weight:600}
  .bar{height:10px;border-radius:5px;background:#2563eb;margin-top:4px}
  .cat{margin-bottom:8px;font-size:14px}
  .cat span{float:right}
  table{width:100%;border-collapse:collapse;font-size:14px}
  td{padding:6px 4px;border-top:1px solid #eee}
  td.amt{text-align:right}
  .del{background:#dc2626;padding:2px 8px}
  .empty{color:#888;font-size:14px}
</style>
</head>
<body>
<h2>Monthly expenses</h2>
<div class="row">
  <input type="text" id="name" placeholder="What did you spend on?">
  <input type="number" id="amt" placeholder="Amount (₹)" min="0">
  <select id="cat">
    <option>Food</option><option>Rent</option><option>Travel</option>
    <option>Bills</option><option>Shopping</option><option>Other</option>
  </select>
  <button id="add" type="button">Add</button>
</div>
<div class="card">
  <div>Total this month</div>
  <div class="total" id="total">₹0</div>
</div>
<div class="card" id="cats"><span class="empty">No spending yet.</span></div>
<div class="card">
  <table id="list"></table>
</div>
<script>
  var items=[];
  function fmt(n){return '₹'+Number(n).toLocaleString('en-IN');}
  function render(){
    var total=0,by={};
    items.forEach(function(i){total+=i.amt;by[i.cat]=(by[i.cat]||0)+i.amt;});
    document.getElementById('total').textContent=fmt(total);
    var c=document.getElementById('cats');
    var keys=Object.keys(by).sort(function(a,b){return by[b]-by[a];});
    c.innerHTML=keys.length?'':'<span class="empty">No spending yet.</span>';
    keys.forEach(function(k){
      var d=document.createElement('div');d.className='cat';
      d.innerHTML=k+'<span>'+fmt(by[k])+'</span><div class="bar" style="width:'+Math.round(by[k]/total*100)+'%"></div>';
      c.appendChild(d);
    });
    var t=document.getElementById('list');
    t.innerHTML='';
    items.forEach(function(i,idx){
      var r=document.createElement('tr');
      r.innerHTML='<td>'+i.name.replace(/</g,'&lt;')+'<br><small>'+i.cat+'</small></td><td class="amt">'+fmt(i.amt)+'</td><td><button class="del" type="button" data-i="'+idx+'">x</button></td>';
      t.appendChild(r);
    });
  }
  document.getElementById('add').onclick=function(){
    var n=document.getElementById('name').value.trim();
    var a=parseFloat(document.getElementById('amt').value);
    if(!n||!(a>0))return;
    items.push({name:n,amt:a,cat:document.getElementById('cat').value});
    document.getElementById('name').value='';
    document.getElementById('amt').value='';
    render();
  };
  document.getElementById('list').onclick=function(e){
    var i=e.target.getAttribute('data-i');
    if(i!==null){items.splice(Number(i),1);render();}
  };
  render();
</script>
</body>
</html>
```

